module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

    parameter WIDTH = 8;
    parameter PRODUCT_WIDTH = 16;

    reg [2:0] mul_en_out_reg;
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;
    wire [7:0] temp [WIDTH-1:0];
    reg [7:0] sum [WIDTH-1:0];
    reg [15:0] mul_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_en_out_reg <= 3'b000;
            mul_a_reg <= 8'b0;
            mul_b_reg <= 8'b0;
        end else begin
            if (mul_en_in) begin
                mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
                mul_a_reg <= mul_a;
                mul_b_reg <= mul_b;
            end else begin
                mul_en_out_reg <= 3'b000;
                mul_a_reg <= 8'b0;
                mul_b_reg <= 8'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (mul_en_out_reg[2]) begin
            sum[0] <= temp[0] + temp[1];
            sum[1] <= temp[2] + temp[3];
            sum[2] <= temp[4] + temp[5];
            sum[3] <= temp[6] + temp[7];
        end
    end

    always @(posedge clk) begin
        if (mul_en_out_reg[2]) begin
            mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
        end
    end

    always @(posedge clk) begin
        if (mul_en_out_reg[2]) begin
            mul_out <= mul_out_reg;
        end else begin
            mul_out <= 16'b0;
        end
    end

    generate
        genvar i;
        for (i = 0; i < WIDTH; i = i + 1) begin : partial_product_gen
            assign temp[i] = mul_a_reg & (mul_b_reg >> i);
        end
    endgenerate

endmodule
